script.text:

function load$&TransferID;$Grid(g) {
	g.add_itemValueChanged(onChange$&TransferID;$);
	g.add_onResponseComplete(on$&TransferID;$ResponseComplete);
	g.add_commandEvent(on$&TransferID;$ExecuteCommand);
	g.$a = {
		tien_gop_von: '[tien_gop_von]:=[ty_le]*[$von_dieu_le]'
	};
}
function dispose$&TransferID;$Grid(g) {
	try {g.remove_commandEvent(on$&TransferID;$ExecuteCommand);} catch (ex) {}
	try {g.remove_itemValueChanged(onChange$&TransferID;$);} catch (ex) {}
	try {g.remove_onResponseComplete(on$&TransferID;$ResponseComplete);} catch (ex) {}
}

function onChange$&TransferID;$(sender, eventArgs) {
	var o = eventArgs.get_object(), g = o.grid, f = g.get_element().parentForm, name = o.field.Name);
	switch (name) {
	case 'ty_le':
			g.validExpression(o, [g.$a.tien_gop_von]);
			break;
		default:
			break;
	}
}
function on$&TransferID;$ExecuteCommand(sender, e) {
	var action = e.type.Action, g = sender, f = g.get_element().parentForm;
	switch (action) {
		case 'Retrieve':
			break;
		default:
			break;
	}
}

function onChangeSite(o){
	var g = o.grid, f = g.get_element().parentForm;
	g.setItemGridBehavior(o, [['ma_vi_tri', '', '', null]]);
	o.parentForm.setItemValue('ma_vi_tri', "");
  o.parentForm.setReferenceKeyFilter('ma_vi_tri');
}

function on$&TransferID;$ResponseComplete(sender, e) {
	var g = e.object, context = e.type.Context, result = e.type.Result, o = e.type.Object;
	switch (context) {
		default:
			break;
	}
}
